import java.util.*;

class Solution {
  public long minimumCost(int[] nums) {
    Arrays.sort(nums);
    String text = Long.toString(nums[nums.length / 2]);
    int len = text.length(), half = (len + 1) / 2;
    long prefix = Long.parseLong(text.substring(0, half));
    List<Long> candidates = new ArrayList<>();
    for (long p : new long[] {prefix - 1, prefix, prefix + 1}) {
      String first = Long.toString(p);
      if (p <= 0 || first.length() != half) continue; // a prefix that gains or loses a digit is covered below
      candidates.add(Long.parseLong(first + new StringBuilder(first.substring(0, len / 2)).reverse()));
    }
    long below = (long) Math.pow(10, len - 1) - 1; // 99..9
    if (below > 0) candidates.add(below);
    candidates.add((long) Math.pow(10, len) + 1); // 10..01
    long answer = Long.MAX_VALUE;
    for (long palindrome : candidates) {
      long cost = 0;
      for (int value : nums) cost += Math.abs(value - palindrome);
      answer = Math.min(answer, cost);
    }
    return answer;
  }
}
